def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((oid, o))

    # If no opponents alive, bid conservatively.
    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday's bids to gauge pressure.
    prev_bids = []
    for _, o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    # Supply pressure: with supply near MIN_SUPPLY, water is scarce.
    scarce = (supply <= (MIN_SUPPLY + 2.0))

    # Urgency based on my HP and consecutive no-water days.
    urgent = (hp <= 2.5) or (no_water_days >= 2)
    moderately_urgent = (hp <= 4.0) or (no_water_days == 1)

    # Core strategy: match/just exceed observed pressure when scarce and I'm not in immediate danger.
    # Use DAILY_SALARY as a scale; cap by budget.
    target = None

    # If someone previously bid extremely high, try to outbid just a bit, but only if I can afford it.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if urgent:
            target = DAILY_SALARY * 0.95
        elif moderately_urgent:
            target = DAILY_SALARY * 0.75
        else:
            # Slightly above high bidder to secure water in scarce situations.
            target = (highest_prev_bid + 2.0) if scarce else max(DAILY_SALARY * 0.6, highest_prev_bid * 0.85)
    else:
        # Otherwise, bid around average pressure; increase if supply is scarce.
        base = max(DAILY_SALARY * 0.5, avg_prev_bid * 0.95)
        if scarce:
            target = base + 10.0
        else:
            target = base

    # If my budget is low, scale down.
    # Keep a minimum bid floor to avoid getting zeroed when urgent.
    budget_safe = max(0.0, budget)
    if budget_safe <= 1.0:
        return 0.0

    # Convert target to a final bid with budget-aware caps.
    # Avoid spending too much when not urgent.
    if urgent:
        cap = budget_safe  # can spend to survive
    else:
        cap = min(budget_safe, DAILY_SALARY * 0.9)

    bid = float(target)
    if bid > cap:
        bid = cap

    # Ensure non-negative.
    if bid < 0.0:
        bid = 0.0

    return bid

