    for k, v in opponents_status.items():
        if v.get('alive'):
            alive[k] = v

    if not alive:
        return float(min(budget, 18.0))

    prev_bids = []
    named_prev = {}
    for name, opp in alive.items():
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            bid = float(bid)
            prev_bids.append(bid)
            named_prev[name] = bid

    david_bid = named_prev.get('David', 48.0)
    eric_bid = named_prev.get('Eric', 126.0)
    cindy_bid = named_prev.get('Cindy', 38.0)
    alex_bid = named_prev.get('Alex', 8.0)

    slots = int(supply // WATER_REQ)
    if slots < 0:
        slots = 0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 1

    if day >= 8:
        danger += 1

    if slots >= 2:
        base = max(12.0, alex_bid + 2.0)
        if danger >= 4:
            bid = max(base, david_bid + 1.25)
        elif danger >= 2:
            bid = max(base, cindy_bid + 1.0)
            bid = min(bid, david_bid - 1.0)
        else:
            bid = base
    else:
        if danger >= 4:
            bid = david_bid + 2.0
        elif danger >= 2:
            bid = david_bid + 0.75
        else:
            bid = max(22.0, cindy_bid + 1.0)

    if eric_bid > 100 and danger < 4:
        bid = min(bid, david_bid + 2.0)

