    if hp > 4 and no_water == 0:
        max_safe = min(max_safe, DAILY_SALARY * 0.62)
    elif hp > 2:
        max_safe = min(max_safe, DAILY_SALARY * 0.82)

    bid = min(bid, max_safe)
    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

